def finding(fid,paper,needle,issue,repair,certainty='description_checked'):
 u=next(x for x in by_paper[paper] if needle in x['text']);pos=u['text'].index(needle)
 findings.append({'id':fid,'unitId':u['unitId'],'paperId':paper,'basis':certainty,'descriptionTextSha256':u['textSha256'],'literalSpan':{'start':pos,'end':pos+len(needle),'text':needle},'issue':issue,'proposedRepair':repair,'scientificStatus':'scope_annotation_proposal_not_primary_scientific_adjudication'})
finding('F01','1007.0027','Galileon phase replace inflation','Framework nomination inflation loses the replace/comparison polarity; this is a noninflationary alternative question, despite reheating appearing later.','Represent Galileon/NEC-violating background and alternative-to-inflation relation, preserving a primordial-perturbation bridge. Do not use inflation as an affirmative system membership.')
